/* public/frases.js · LAS FRASES DE LA PORTADA (ago 2026)
   ─────────────────────────────────────────────────────────────────────────────
   El titular de la landing rota una frase sobre lo público como bien común y el
   derecho de la empresa pequeña a competir. El dueño las calificó de éxito y
   pidió muchas más, con rotación más lenta y en español profesional (registro
   formal, «usted»; nada de voseo). Reglas: sin emojis, sin jerga del sistema,
   sin cifras que prometan nada, una idea por frase, ninguna repetida. Módulo
   UMD: lo lee onboarding.js en el navegador y la suite en Node. */
